import XCTest
@testable import HusrevityJS

/// Asserts that the JavaScriptCore bundle reproduces the outputs of the real TypeScript
/// implementations. Expectations live in Fixtures/parity-cases.json, generated by
/// scripts/gen-parity-cases.ts (never edit by hand).
final class CoreJSParityTests: XCTestCase {
    private struct ParseCase: Decodable {
        let input: String
        let now: String
        let expected: ParsedDraft
    }

    private struct ExpandCase: Decodable {
        struct Occurrence: Decodable {
            let occursOn: String
            let occursAt: String
        }
        let name: String
        let rrule: String
        let start: String
        let from: String
        let to: String
        let zone: String
        let expected: [Occurrence]
    }

    private struct InvalidCase: Decodable {
        let name: String
        let rrule: String
    }

    private struct EngineCase: Decodable {
        let input: String
        let now: String
        let serverExpected: ParsedDraft
    }

    private struct ParityFile: Decodable {
        let parse: [ParseCase]
        let engineDependent: [EngineCase]
        let expand: [ExpandCase]
        let invalidExpand: [InvalidCase]
    }

    private static func loadParity() throws -> ParityFile {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/parity-cases.json")
        return try JSONDecoder().decode(ParityFile.self, from: Data(contentsOf: url))
    }

    private static func date(_ iso: String) throws -> Date {
        let f = ISO8601DateFormatter()
        f.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return try XCTUnwrap(f.date(from: iso), "bad ISO date \(iso)")
    }

    private static func iso(_ date: Date) -> String {
        let f = ISO8601DateFormatter()
        f.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return f.string(from: date)
    }

    func testEveryParseCaseMatchesTheTypeScriptParser() throws {
        let core = try CoreJS()
        let cases = try Self.loadParity().parse
        XCTAssertGreaterThan(cases.count, 100)
        for c in cases {
            let got = try core.parseQuickAdd(
                c.input, now: Self.date(c.now), timeZone: TimeZone(identifier: "Europe/Istanbul")!)
            XCTAssertEqual(got, c.expected, "input \"\(c.input)\" now \(c.now)")
        }
    }

    /// Uppercase "I" vs dotless "ı" under /i is engine-dependent (V8 and Bun: no match; system
    /// JavaScriptCore: match). Either outcome is accepted, but nothing else may differ.
    func testEngineDependentCaseFoldingStaysWithinTheTwoKnownOutcomes() throws {
        let core = try CoreJS()
        for c in try Self.loadParity().engineDependent {
            let got = try core.parseQuickAdd(
                c.input, now: Self.date(c.now), timeZone: TimeZone(identifier: "Europe/Istanbul")!)
            let strict = c.serverExpected
            let folded = ParsedDraft(
                title: "Toplantı", scheduledAt: "2026-10-19T06:00:00.000Z")
            XCTAssertTrue(got == strict || got == folded, "\(c.input) -> \(got)")
        }
    }

    func testEveryExpandCaseMatchesTheTypeScriptImplementation() throws {
        let core = try CoreJS()
        let cases = try Self.loadParity().expand
        XCTAssertGreaterThan(cases.count, 20)
        for c in cases {
            let got = try core.expandOccurrences(
                rrule: c.rrule,
                start: Self.date(c.start),
                from: Self.date(c.from),
                to: Self.date(c.to),
                timeZone: TimeZone(identifier: c.zone)!)
            XCTAssertEqual(got.map(Self.iso), c.expected.map(\.occursAt), c.name)
        }
    }

    func testInvalidRulesThrowInsteadOfCrashing() throws {
        let core = try CoreJS()
        for c in try Self.loadParity().invalidExpand {
            XCTAssertThrowsError(
                try core.expandOccurrences(
                    rrule: c.rrule, start: Date(timeIntervalSince1970: 1_767_600_000),
                    from: Date(timeIntervalSince1970: 1_767_600_000),
                    to: Date(timeIntervalSince1970: 1_770_000_000),
                    timeZone: TimeZone(identifier: "Europe/Istanbul")!),
                c.name
            ) { error in
                XCTAssertTrue(error is CoreJSError, "\(c.name): \(error)")
            }
        }
    }
}
